insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'law_ethics', 'กฎหมายและจรรยาบรรณวิชาชีพ (Law & Ethics)', 18
