-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'งานวิศวกรรมไฟฟ้าประเภทใดที่กฎกระทรวงกำหนดวิชาชีพวิศวกรรมควบคุมของไทย กำหนดให้ต้องมีผู้ได้รับใบอนุญาตประกอบวิชาชีพวิศวกรรมควบคุมเป็นผู้ดำเนินการ', 'โดยทั่วไปครอบคลุมงานออกแบบ งานควบคุมการสร้างหรือการผลิต และงานพิจารณาตรวจสอบระบบไฟฟ้ากำลังที่มีขนาดหรือความซับซ้อนเกินเกณฑ์ที่กฎหมายกำหนด เช่น ระบบไฟฟ้าของอาคารขนาดใหญ่หรือโรงงานอุตสาหกรรมที่มีความเสี่ยงสูง', 'ขอบเขตที่ชัดเจนของงานที่ต้องมีวิศวกรควบคุมกำหนดไว้ในกฎกระทรวงและประกาศที่เกี่ยวข้องซึ่งอาจมีการปรับปรุงเป็นระยะ ผู้ประกอบวิชาชีพจึงควรตรวจสอบฉบับล่าสุดที่บังคับใช้อยู่เสมอก่อนรับงาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'งานวิศวกรรมไฟฟ้าประเภทใดที่กฎกระทรวงกำหนดวิชาชีพวิศวกรรมควบคุมของไทย กำหนดให้ต้องมีผู้ได้รับใบอนุญาตประกอบวิชาชีพวิศวกรรมควบคุมเป็นผู้ดำเนินการ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ใบอนุญาตประกอบวิชาชีพวิศวกรรมควบคุมสาขาไฟฟ้า แบ่งระดับตามความสามารถและประสบการณ์อย่างไร', 'โดยทั่วไปแบ่งเป็นระดับภาคี สามัญ และวุฒิวิศวกร โดยแต่ละระดับมีขอบเขตงานและขนาดโครงการที่สามารถรับผิดชอบได้แตกต่างกัน ระดับภาคีมักจำกัดขอบเขตงานและขนาดโครงการ ระดับสามัญมีขอบเขตกว้างขึ้นตามประสบการณ์ที่สั่งสม และระดับวุฒิวิศวกรมีขอบเขตกว้างที่สุดสำหรับโครงการที่มีความซับซ้อนหรือขนาดใหญ่เป็นพิเศษ', 'การเลื่อนระดับใบอนุญาตต้องผ่านกระบวนการประเมินประสบการณ์และผลงานตามเกณฑ์ที่สภาวิชาชีพกำหนด ซึ่งรวมถึงการนำเสนอผลงานเด่นและการตอบข้อซักถามจากคณะกรรมการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ใบอนุญาตประกอบวิชาชีพวิศวกรรมควบคุมสาขาไฟฟ้า แบ่งระดับตามความสามารถและประสบการณ์อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ลงนามรับรองแบบระบบไฟฟ้าที่ตนเองไม่ได้เป็นผู้ออกแบบจริง จึงถือเป็นการกระทำที่ผิดจรรยาบรรณวิชาชีพอย่างร้ายแรง', 'เพราะการลงนามรับรองแบบเป็นการยืนยันความรับผิดชอบทางวิชาชีพว่าผู้ลงนามได้ตรวจสอบและมั่นใจในความถูกต้องปลอดภัยของแบบนั้นด้วยตนเอง หากลงนามในแบบที่ตนไม่ได้ตรวจสอบอย่างแท้จริง อาจทำให้ระบบที่มีข้อบกพร่องผ่านการรับรองไปสู่การก่อสร้างจริง ซึ่งอาจก่อให้เกิดอันตรายร้ายแรงต่อชีวิตและทรัพย์สินของผู้ใช้งานในอนาคต', 'การกระทำเช่นนี้มักเรียกว่าการรับจ้างเซ็นแบบ ซึ่งเป็นการละเมิดจรรยาบรรณวิชาชีพขั้นพื้นฐาน และในหลายกรณีอาจนำไปสู่การถูกเพิกถอนใบอนุญาตประกอบวิชาชีพหากตรวจพบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ลงนามรับรองแบบระบบไฟฟ้าที่ตนเองไม่ได้เป็นผู้ออกแบบจริง จึงถือเป็นการกระทำที่ผิดจรรยาบรรณวิชาชีพอย่างร้ายแรง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'หากวิศวกรไฟฟ้าพบว่าแบบที่ตนได้รับมอบหมายให้ตรวจสอบมีข้อบกพร่องด้านความปลอดภัยที่อาจก่อให้เกิดอันตราย แต่ผู้ว่าจ้างเร่งรัดให้อนุมัติแบบเพื่อความรวดเร็ว วิศวกรควรปฏิบัติตนอย่างไรตามหลักจรรยาบรรณ', 'วิศวกรควรยึดหลักความปลอดภัยของสาธารณะเป็นสำคัญเหนือกว่าความต้องการของผู้ว่าจ้าง โดยแจ้งข้อบกพร่องที่พบอย่างชัดเจนพร้อมเหตุผลทางเทคนิค และปฏิเสธที่จะอนุมัติแบบจนกว่าข้อบกพร่องนั้นจะได้รับการแก้ไขอย่างเหมาะสม แม้จะขัดกับความต้องการด้านเวลาของผู้ว่าจ้างก็ตาม', 'หลักการนี้สอดคล้องกับจรรยาบรรณวิชาชีพวิศวกรรมที่ถือว่าความปลอดภัยของสาธารณชนเป็นความรับผิดชอบสูงสุดของวิศวกร เหนือกว่าผลประโยชน์ทางธุรกิจของผู้ว่าจ้างหรือความสะดวกส่วนตัวของวิศวกรเอง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'หากวิศวกรไฟฟ้าพบว่าแบบที่ตนได้รับมอบหมายให้ตรวจสอบมีข้อบกพร่องด้านความปลอดภัยที่อาจก่อให้เกิดอันตราย แต่ผู้ว่าจ้างเร่งรัดให้อนุมัติแบบเพื่อความรวดเร็ว วิศวกรควรปฏิบัติตนอย่างไรตามหลักจรรยาบรรณ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงต้องรักษาความรู้และทักษะของตนให้ทันสมัยอยู่เสมอผ่านการพัฒนาวิชาชีพต่อเนื่อง (Continuing Professional Development, CPD)', 'เพราะเทคโนโลยีทางไฟฟ้ามีการพัฒนาอย่างรวดเร็ว มาตรฐานและกฎหมายที่เกี่ยวข้องก็มีการปรับปรุงเป็นระยะ หากวิศวกรไม่พัฒนาความรู้ให้ทันสมัย อาจนำความรู้ที่ล้าสมัยมาใช้ในการออกแบบหรือตัดสินใจทางวิชาชีพ ซึ่งอาจไม่สอดคล้องกับมาตรฐานความปลอดภัยหรือแนวปฏิบัติที่ดีที่สุดในปัจจุบัน', 'หลายประเทศรวมถึงระบบใบอนุญาตวิชาชีพของไทยกำหนดให้มีการสะสมหน่วยกิจกรรมการพัฒนาวิชาชีพต่อเนื่องเป็นเงื่อนไขสำคัญสำหรับการต่ออายุใบอนุญาตหรือการเลื่อนระดับใบอนุญาตวิชาชีพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงต้องรักษาความรู้และทักษะของตนให้ทันสมัยอยู่เสมอผ่านการพัฒนาวิชาชีพต่อเนื่อง (Continuing Professional Development, CPD)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ความขัดแย้งทางผลประโยชน์ (Conflict of Interest) ในงานวิศวกรรมไฟฟ้าอาจเกิดขึ้นในลักษณะใดได้บ้าง', 'อาจเกิดขึ้นได้หลายลักษณะ เช่น วิศวกรที่รับหน้าที่ตรวจสอบและรับรองผลงานของบริษัทที่ตนเองมีส่วนได้ส่วนเสียทางการเงิน หรือวิศวกรที่กำหนดข้อกำหนดในการออกแบบให้เอื้อประโยชน์แก่ผลิตภัณฑ์เฉพาะยี่ห้อที่ตนได้รับผลตอบแทนพิเศษจากผู้จำหน่าย โดยไม่คำนึงถึงความเหมาะสมทางเทคนิคที่แท้จริง', 'จรรยาบรรณวิชาชีพกำหนดให้วิศวกรต้องเปิดเผยความขัดแย้งทางผลประโยชน์ที่อาจเกิดขึ้นให้ทุกฝ่ายที่เกี่ยวข้องทราบอย่างโปร่งใส และหลีกเลี่ยงสถานการณ์ที่ผลประโยชน์ส่วนตัวอาจส่งผลกระทบต่อความเป็นกลางในการตัดสินใจทางวิชาชีพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ความขัดแย้งทางผลประโยชน์ (Conflict of Interest) ในงานวิศวกรรมไฟฟ้าอาจเกิดขึ้นในลักษณะใดได้บ้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงต้องรักษาความลับของข้อมูลลูกค้าหรือโครงการที่ตนได้รับมอบหมาย แม้จะสิ้นสุดสัญญาว่าจ้างไปแล้วก็ตาม', 'เพราะข้อมูลทางเทคนิคของโครงการ เช่น การออกแบบระบบไฟฟ้าเฉพาะหรือข้อมูลทางธุรกิจของลูกค้า อาจเป็นข้อมูลที่มีมูลค่าทางการแข่งขันหรือมีความอ่อนไหวต่อความปลอดภัย การเปิดเผยข้อมูลเหล่านี้โดยไม่ได้รับอนุญาตอาจก่อให้เกิดความเสียหายต่อลูกค้า ทั้งด้านธุรกิจและด้านความปลอดภัย', 'หน้าที่การรักษาความลับนี้ถือเป็นข้อผูกพันทางจรรยาบรรณที่ยังคงมีผลต่อเนื่องแม้ความสัมพันธ์ทางสัญญาจะสิ้นสุดลงแล้ว เว้นแต่จะได้รับความยินยอมจากลูกค้าหรือมีข้อกำหนดทางกฎหมายที่บังคับให้ต้องเปิดเผย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงต้องรักษาความลับของข้อมูลลูกค้าหรือโครงการที่ตนได้รับมอบหมาย แม้จะสิ้นสุดสัญญาว่าจ้างไปแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงมีหน้าที่ต้องรายงานความผิดปกติหรือความเสี่ยงด้านความปลอดภัยที่ร้ายแรงที่ตนพบเห็น แม้จะไม่ได้อยู่ในขอบเขตงานที่ตนได้รับมอบหมายโดยตรง', 'เพราะจรรยาบรรณวิชาชีพวิศวกรรมให้ความสำคัญสูงสุดกับความปลอดภัยของสาธารณชน หากวิศวกรพบเห็นความเสี่ยงร้ายแรงแต่เลือกที่จะเพิกเฉยเพียงเพราะไม่ใช่หน้าที่โดยตรงของตน อาจถือเป็นการละเลยความรับผิดชอบพื้นฐานของวิศวกรที่มีต่อสังคม แม้จะไม่มีข้อผูกพันทางสัญญาให้ต้องดำเนินการก็ตาม', 'ในทางปฏิบัติ การรายงานความเสี่ยงที่พบควรทำผ่านช่องทางที่เหมาะสม เช่น แจ้งเจ้าของอาคารหรือหน่วยงานที่รับผิดชอบโดยตรง เพื่อให้เกิดการแก้ไขปัญหาอย่างมีประสิทธิภาพและไม่ก้าวก่ายขอบเขตความรับผิดชอบของผู้อื่นเกินความจำเป็น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงมีหน้าที่ต้องรายงานความผิดปกติหรือความเสี่ยงด้านความปลอดภัยที่ร้ายแรงที่ตนพบเห็น แม้จะไม่ได้อยู่ในขอบเขตงานที่ตนได้รับมอบหมายโดยตรง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การกำหนดค่าธรรมเนียมวิชาชีพ (Professional Fee) สำหรับงานออกแบบระบบไฟฟ้า ควรอยู่บนพื้นฐานหลักการใดตามจรรยาบรรณวิชาชีพ', 'ควรอยู่บนพื้นฐานของความเหมาะสมกับขอบเขตงาน ความซับซ้อน ความรับผิดชอบ และประสบการณ์ที่ต้องใช้ในการดำเนินงานนั้นอย่างแท้จริง ไม่ควรกำหนดค่าธรรมเนียมต่ำเกินสมควรจนไม่สามารถดำเนินงานได้อย่างมีคุณภาพและปลอดภัยเพียงเพื่อแข่งขันด้านราคากับวิศวกรรายอื่น', 'การแข่งขันด้านราคาที่ต่ำเกินไปในวงการวิศวกรรมอาจนำไปสู่การลดคุณภาพงานเพื่อรักษาผลกำไร ซึ่งอาจส่งผลเสียต่อความปลอดภัยของโครงการในระยะยาว จรรยาบรรณวิชาชีพจึงมักส่งเสริมให้มีการแข่งขันบนพื้นฐานคุณภาพและความสามารถมากกว่าราคาต่ำเพียงอย่างเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การกำหนดค่าธรรมเนียมวิชาชีพ (Professional Fee) สำหรับงานออกแบบระบบไฟฟ้า ควรอยู่บนพื้นฐานหลักการใดตามจรรยาบรรณวิชาชีพ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงควรหลีกเลี่ยงการวิพากษ์วิจารณ์ผลงานของวิศวกรรายอื่นในลักษณะที่ไม่สร้างสรรค์หรือมีเจตนาทำลายชื่อเสียง', 'เพราะการวิพากษ์วิจารณ์ที่ไม่สร้างสรรค์หรือมีเจตนาแอบแฝงเพื่อผลประโยชน์ทางธุรกิจของตนเอง อาจสร้างความเสียหายต่อชื่อเสียงของวิศวกรผู้อื่นโดยไม่เป็นธรรม และบั่นทอนความน่าเชื่อถือของวิชาชีพวิศวกรรมโดยรวมในสายตาของสาธารณชน', 'จรรยาบรรณวิชาชีพมักส่งเสริมให้วิศวกรแสดงความคิดเห็นทางเทคนิคอย่างสร้างสรรค์และมีหลักฐานรองรับ หากพบข้อบกพร่องในผลงานของผู้อื่นควรสื่อสารผ่านช่องทางที่เหมาะสม เช่น การรายงานต่อหน่วยงานที่เกี่ยวข้อง แทนการวิจารณ์ต่อสาธารณะโดยไม่มีหลักฐานหรือกระบวนการที่เป็นธรรม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงควรหลีกเลี่ยงการวิพากษ์วิจารณ์ผลงานของวิศวกรรายอื่นในลักษณะที่ไม่สร้างสรรค์หรือมีเจตนาทำลายชื่อเสียง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การปลอมแปลงหรือบิดเบือนผลการทดสอบระบบไฟฟ้า เพื่อให้ผ่านเกณฑ์การตรวจรับงาน ถือเป็นการละเมิดจรรยาบรรณในระดับใด และมีผลกระทบอย่างไร', 'ถือเป็นการละเมิดจรรยาบรรณวิชาชีพในระดับร้ายแรงที่สุดประเภทหนึ่ง เพราะเป็นการบิดเบือนข้อเท็จจริงที่เกี่ยวข้องโดยตรงกับความปลอดภัยของระบบ ผลกระทบอาจนำไปสู่การใช้งานระบบที่ไม่ปลอดภัยจริง ซึ่งอาจก่อให้เกิดอันตรายร้ายแรงต่อชีวิตและทรัพย์สินในอนาคตโดยที่ผู้ใช้งานไม่ทราบถึงความเสี่ยงที่แท้จริง', 'การกระทำเช่นนี้นอกจากจะเป็นการละเมิดจรรยาบรรณวิชาชีพแล้ว ในหลายกรณียังอาจเข้าข่ายความผิดทางกฎหมายอาญาหากนำไปสู่ความเสียหายต่อชีวิตหรือทรัพย์สิน ซึ่งมีบทลงโทษที่รุนแรงกว่าเพียงการเพิกถอนใบอนุญาตวิชาชีพ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การปลอมแปลงหรือบิดเบือนผลการทดสอบระบบไฟฟ้า เพื่อให้ผ่านเกณฑ์การตรวจรับงาน ถือเป็นการละเมิดจรรยาบรรณในระดับใด และมีผลกระทบอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ทำงานเป็นที่ปรึกษาให้กับหลายบริษัทที่เป็นคู่แข่งกัน จึงต้องมีความระมัดระวังเป็นพิเศษด้านการรักษาความลับทางการค้า', 'เพราะวิศวกรที่ปรึกษาอาจเข้าถึงข้อมูลทางเทคนิคหรือกลยุทธ์ทางธุรกิจของบริษัทหนึ่ง ซึ่งหากนำไปเปิดเผยหรือใช้ประโยชน์ให้แก่บริษัทคู่แข่งอีกรายที่ตนให้บริการอยู่ด้วย แม้จะไม่ได้ตั้งใจ ก็อาจก่อให้เกิดความเสียหายทางธุรกิจร้ายแรงและถือเป็นการละเมิดความไว้วางใจของลูกค้ารายแรกอย่างชัดเจน', 'วิศวกรที่ปรึกษาในสถานการณ์เช่นนี้ควรมีมาตรการป้องกันที่ชัดเจน เช่น การแยกทีมงานที่รับผิดชอบแต่ละโครงการ หรือในบางกรณีอาจต้องปฏิเสธการรับงานจากบริษัทคู่แข่งเพื่อหลีกเลี่ยงความขัดแย้งทางผลประโยชน์ที่อาจเกิดขึ้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ทำงานเป็นที่ปรึกษาให้กับหลายบริษัทที่เป็นคู่แข่งกัน จึงต้องมีความระมัดระวังเป็นพิเศษด้านการรักษาความลับทางการค้า'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดกฎหมายควบคุมอาคารจึงกำหนดให้ต้องมีการตรวจสอบระบบไฟฟ้าของอาคารบางประเภทเป็นระยะ แม้อาคารจะผ่านการตรวจรับเมื่อก่อสร้างเสร็จแล้วก็ตาม', 'เพราะระบบไฟฟ้าและอุปกรณ์ที่เกี่ยวข้องมีการเสื่อมสภาพตามการใช้งานและอายุ ความเสี่ยงด้านความปลอดภัยที่ไม่มีอยู่ในวันที่ก่อสร้างเสร็จอาจพัฒนาขึ้นภายหลังจากการใช้งานเป็นเวลานาน การตรวจสอบเป็นระยะช่วยให้ตรวจพบและแก้ไขปัญหาได้ก่อนที่จะนำไปสู่อุบัติเหตุร้ายแรง โดยเฉพาะในอาคารสาธารณะที่มีผู้ใช้งานจำนวนมาก', 'กฎหมายมักกำหนดให้อาคารบางประเภทที่มีความเสี่ยงสูงหรือมีผู้ใช้งานจำนวนมาก เช่น อาคารสูงหรืออาคารขนาดใหญ่พิเศษ ต้องมีการตรวจสอบสภาพอาคารรวมถึงระบบไฟฟ้าโดยผู้ตรวจสอบอาคารที่ได้รับใบอนุญาตเป็นประจำตามรอบเวลาที่กำหนด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดกฎหมายควบคุมอาคารจึงกำหนดให้ต้องมีการตรวจสอบระบบไฟฟ้าของอาคารบางประเภทเป็นระยะ แม้อาคารจะผ่านการตรวจรับเมื่อก่อสร้างเสร็จแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ผู้ตรวจสอบอาคาร (Building Inspector) ที่ตรวจสอบระบบไฟฟ้าของอาคาร มีความรับผิดชอบทางวิชาชีพแตกต่างจากวิศวกรผู้ออกแบบระบบไฟฟ้าอย่างไร', 'วิศวกรผู้ออกแบบมีหน้าที่รับผิดชอบต่อความถูกต้องและความปลอดภัยของการออกแบบระบบตั้งแต่ต้น ในขณะที่ผู้ตรวจสอบอาคารมีหน้าที่ประเมินสภาพจริงของระบบที่ใช้งานอยู่ว่ายังคงอยู่ในสภาพปลอดภัยตามที่ออกแบบไว้หรือไม่ รวมถึงตรวจสอบว่าไม่มีการดัดแปลงระบบที่ไม่ได้มาตรฐานเกิดขึ้นในภายหลัง', 'ทั้งสองบทบาทมีความสำคัญเสริมกันในการรักษาความปลอดภัยของอาคารตลอดวงจรชีวิต ตั้งแต่ขั้นตอนออกแบบก่อสร้างไปจนถึงการใช้งานระยะยาว โดยแต่ละบทบาทต้องรับผิดชอบทางวิชาชีพตามขอบเขตหน้าที่ของตนอย่างเคร่งครัด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ผู้ตรวจสอบอาคาร (Building Inspector) ที่ตรวจสอบระบบไฟฟ้าของอาคาร มีความรับผิดชอบทางวิชาชีพแตกต่างจากวิศวกรผู้ออกแบบระบบไฟฟ้าอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ให้คำปรึกษาแก่ประชาชนทั่วไปในเรื่องความปลอดภัยทางไฟฟ้า จึงควรระมัดระวังไม่ให้คำแนะนำที่เกินขอบเขตความเชี่ยวชาญของตน', 'เพราะการให้คำแนะนำที่ไม่ถูกต้องหรือเกินความเชี่ยวชาญที่แท้จริง อาจนำไปสู่การตัดสินใจที่ผิดพลาดของผู้รับคำแนะนำ ซึ่งอาจก่อให้เกิดอันตรายจากการปฏิบัติตามคำแนะนำที่ไม่ถูกต้องนั้น วิศวกรควรตระหนักถึงขอบเขตความเชี่ยวชาญของตนเองและแนะนำให้ปรึกษาผู้เชี่ยวชาญเฉพาะทางเพิ่มเติมเมื่อจำเป็น', 'หลักการนี้สอดคล้องกับจรรยาบรรณวิชาชีพที่กำหนดให้วิศวกรปฏิบัติงานเฉพาะในสาขาที่ตนมีความสามารถและประสบการณ์เพียงพอเท่านั้น ไม่ควรรับงานหรือให้คำแนะนำในเรื่องที่อยู่นอกเหนือความเชี่ยวชาญของตนโดยไม่มีการศึกษาเพิ่มเติมหรือปรึกษาผู้เชี่ยวชาญที่เหมาะสม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ให้คำปรึกษาแก่ประชาชนทั่วไปในเรื่องความปลอดภัยทางไฟฟ้า จึงควรระมัดระวังไม่ให้คำแนะนำที่เกินขอบเขตความเชี่ยวชาญของตน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการลงนามรับรองความปลอดภัยของระบบไฟฟ้าที่วิศวกรไม่ได้ตรวจสอบด้วยตนเองอย่างครบถ้วน แต่อาศัยรายงานจากผู้ใต้บังคับบัญชาเพียงอย่างเดียว จึงต้องกระทำด้วยความระมัดระวังเป็นพิเศษ', 'เพราะแม้จะเป็นเรื่องปกติที่วิศวกรอาวุโสจะมอบหมายงานตรวจสอบรายละเอียดบางส่วนให้ผู้ใต้บังคับบัญชาดำเนินการ แต่ความรับผิดชอบทางวิชาชีพในการลงนามรับรองยังคงตกอยู่กับวิศวกรผู้ลงนามเป็นหลัก วิศวกรจึงต้องมั่นใจว่ากระบวนการตรวจสอบของผู้ใต้บังคับบัญชามีความน่าเชื่อถือเพียงพอ และควรมีการสุ่มตรวจสอบหรือทบทวนผลด้วยตนเองในส่วนที่มีความเสี่ยงสูงก่อนลงนามรับรอง', 'การมอบหมายงานที่เหมาะสมพร้อมระบบตรวจสอบที่น่าเชื่อถือ แตกต่างจากการลงนามโดยไม่มีการตรวจสอบใดๆ เลย ซึ่งเข้าข่ายการรับจ้างเซ็นแบบตามที่กล่าวถึงก่อนหน้า วิศวกรจึงต้องแยกแยะขอบเขตความรับผิดชอบนี้ให้ชัดเจนในทางปฏิบัติ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการลงนามรับรองความปลอดภัยของระบบไฟฟ้าที่วิศวกรไม่ได้ตรวจสอบด้วยตนเองอย่างครบถ้วน แต่อาศัยรายงานจากผู้ใต้บังคับบัญชาเพียงอย่างเดียว จึงต้องกระทำด้วยความระมัดระวังเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงมีหน้าที่ให้ข้อมูลที่ถูกต้องครบถ้วนแก่ลูกค้า แม้ข้อมูลนั้นอาจทำให้ลูกค้าตัดสินใจไม่ว่าจ้างงานหรือเลือกทางเลือกที่มีมูลค่างานต่ำกว่า', 'เพราะหน้าที่พื้นฐานของวิศวกรคือการให้บริการที่ซื่อสัตย์และเป็นประโยชน์สูงสุดต่อลูกค้าตามหลักวิชาการที่ถูกต้อง ไม่ใช่การแสวงหาผลประโยชน์สูงสุดสำหรับตนเองโดยไม่คำนึงถึงความต้องการที่แท้จริงของลูกค้า การปกปิดหรือบิดเบือนข้อมูลเพื่อให้ได้งานที่มีมูลค่าสูงกว่าถือเป็นการละเมิดความไว้วางใจของลูกค้า', 'จรรยาบรรณวิชาชีพที่ดีส่งเสริมให้วิศวกรให้คำแนะนำที่เหมาะสมกับความต้องการที่แท้จริงของลูกค้า แม้บางครั้งอาจหมายถึงการแนะนำทางเลือกที่มีมูลค่างานต่ำกว่าสิ่งที่วิศวกรอาจได้รับประโยชน์มากกว่า เพราะความน่าเชื่อถือระยะยาวมีค่ามากกว่าผลประโยชน์ระยะสั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงมีหน้าที่ให้ข้อมูลที่ถูกต้องครบถ้วนแก่ลูกค้า แม้ข้อมูลนั้นอาจทำให้ลูกค้าตัดสินใจไม่ว่าจ้างงานหรือเลือกทางเลือกที่มีมูลค่างานต่ำกว่า'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ค้นพบว่าโครงการที่ตนเคยออกแบบไว้ในอดีต มีข้อบกพร่องที่อาจเป็นอันตราย ควรดำเนินการแจ้งเตือนแม้จะผ่านมานานแล้วและอาจกระทบต่อชื่อเสียงของตนเอง', 'เพราะความปลอดภัยของสาธารณชนที่ใช้งานระบบนั้นมีความสำคัญเหนือกว่าความกังวลเรื่องชื่อเสียงส่วนตัวของวิศวกร การนิ่งเฉยต่อความเสี่ยงที่ทราบอยู่แล้วเพื่อปกป้องชื่อเสียงของตนเอง อาจนำไปสู่อันตรายร้ายแรงต่อผู้ใช้งานที่ไม่ทราบถึงความเสี่ยงนั้น ซึ่งขัดต่อหลักจรรยาบรรณพื้นฐานของวิชาชีพวิศวกรรมอย่างชัดเจน', 'ในทางปฏิบัติ วิศวกรควรแจ้งเตือนผ่านช่องทางที่เหมาะสม เช่น แจ้งเจ้าของอาคารหรือผู้รับผิดชอบดูแลระบบโดยตรง พร้อมข้อเสนอแนะแนวทางแก้ไข ซึ่งการยอมรับความผิดพลาดและดำเนินการแก้ไขอย่างมืออาชีพ มักได้รับการยอมรับมากกว่าการปกปิดที่อาจนำไปสู่ผลกระทบร้ายแรงกว่าในภายหลัง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ค้นพบว่าโครงการที่ตนเคยออกแบบไว้ในอดีต มีข้อบกพร่องที่อาจเป็นอันตราย ควรดำเนินการแจ้งเตือนแม้จะผ่านมานานแล้วและอาจกระทบต่อชื่อเสียงของตนเอง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการรับงานออกแบบระบบไฟฟ้าที่เกินขอบเขตความสามารถหรือประสบการณ์ของตนเอง โดยไม่แจ้งให้ลูกค้าทราบ จึงถือเป็นการละเมิดจรรยาบรรณวิชาชีพ', 'เพราะการดำเนินงานที่เกินขีดความสามารถโดยไม่มีการเตรียมความพร้อมที่เหมาะสม เช่น การขอคำปรึกษาจากผู้เชี่ยวชาญเฉพาะทางหรือการศึกษาเพิ่มเติมอย่างจริงจัง มีความเสี่ยงสูงที่จะเกิดข้อผิดพลาดในการออกแบบที่วิศวกรอาจไม่ตระหนักถึงเนื่องจากขาดความรู้หรือประสบการณ์ที่เพียงพอในเรื่องนั้น ซึ่งอาจส่งผลกระทบต่อความปลอดภัยของระบบในที่สุด', 'วิศวกรที่มีจรรยาบรรณที่ดีควรประเมินความสามารถของตนเองอย่างตรงไปตรงมา และหากพบว่างานที่ได้รับมอบหมายเกินขอบเขตความเชี่ยวชาญ ควรแจ้งให้ลูกค้าทราบและเสนอแนวทาง เช่น การร่วมงานกับผู้เชี่ยวชาญเฉพาะทางเพิ่มเติม แทนที่จะรับงานไปโดยปกปิดข้อจำกัดของตนเอง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการรับงานออกแบบระบบไฟฟ้าที่เกินขอบเขตความสามารถหรือประสบการณ์ของตนเอง โดยไม่แจ้งให้ลูกค้าทราบ จึงถือเป็นการละเมิดจรรยาบรรณวิชาชีพ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการทำสัญญาว่าจ้างงานวิศวกรรมไฟฟ้า จึงควรระบุขอบเขตความรับผิดชอบและข้อจำกัดความรับผิด (Limitation of Liability) ไว้อย่างชัดเจน', 'เพื่อป้องกันความเข้าใจที่ไม่ตรงกันระหว่างวิศวกรและลูกค้าเกี่ยวกับขอบเขตของงานที่รับผิดชอบ และเพื่อกำหนดกรอบความรับผิดที่เหมาะสมและเป็นธรรมต่อทั้งสองฝ่าย เนื่องจากความเสียหายที่อาจเกิดขึ้นจากระบบไฟฟ้าอาจมีมูลค่าสูงมาก การมีข้อกำหนดที่ชัดเจนช่วยลดข้อพิพาททางกฎหมายที่อาจเกิดขึ้นในอนาคต', 'อย่างไรก็ตาม ข้อจำกัดความรับผิดที่กำหนดไว้ในสัญญาไม่สามารถใช้เป็นข้ออ้างเพื่อหลีกเลี่ยงความรับผิดชอบทางวิชาชีพขั้นพื้นฐานด้านความปลอดภัย โดยเฉพาะในกรณีที่เกิดจากความประมาทเลินเล่ออย่างร้ายแรงของวิศวกรเอง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการทำสัญญาว่าจ้างงานวิศวกรรมไฟฟ้า จึงควรระบุขอบเขตความรับผิดชอบและข้อจำกัดความรับผิด (Limitation of Liability) ไว้อย่างชัดเจน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงควรหลีกเลี่ยงการรับผลประโยชน์หรือของกำนัลจากผู้ผลิตหรือผู้จำหน่ายอุปกรณ์ไฟฟ้า ในระหว่างที่กำลังดำเนินการออกแบบหรือคัดเลือกผลิตภัณฑ์ให้กับโครงการ', 'เพราะการรับผลประโยชน์ดังกล่าวอาจส่งผลกระทบต่อความเป็นกลางในการตัดสินใจของวิศวกร ทำให้เลือกใช้ผลิตภัณฑ์ตามผลประโยชน์ส่วนตัวมากกว่าความเหมาะสมทางเทคนิคที่แท้จริงสำหรับโครงการนั้น ซึ่งขัดต่อหลักการที่วิศวกรต้องตัดสินใจโดยคำนึงถึงผลประโยชน์สูงสุดของลูกค้าและโครงการเป็นหลัก', 'แม้ในบางวัฒนธรรมการรับของกำนัลเล็กน้อยอาจเป็นเรื่องปกติทางสังคม แต่ในบริบทวิชาชีพวิศวกรรม ควรมีความระมัดระวังและความโปร่งใสเป็นพิเศษ เพื่อรักษาความน่าเชื่อถือของกระบวนการตัดสินใจทางเทคนิคให้ปราศจากข้อครหาเรื่องผลประโยชน์ทับซ้อน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงควรหลีกเลี่ยงการรับผลประโยชน์หรือของกำนัลจากผู้ผลิตหรือผู้จำหน่ายอุปกรณ์ไฟฟ้า ในระหว่างที่กำลังดำเนินการออกแบบหรือคัดเลือกผลิตภัณฑ์ให้กับโครงการ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ทำงานในภาครัฐหรือหน่วยงานกำกับดูแล จึงต้องมีมาตรฐานจรรยาบรรณที่เข้มงวดเป็นพิเศษเมื่อเทียบกับวิศวกรที่ทำงานในภาคเอกชน', 'เพราะการตัดสินใจของวิศวกรในภาครัฐหรือหน่วยงานกำกับดูแล เช่น การอนุมัติแบบหรือการตรวจสอบมาตรฐาน มีผลกระทบต่อสาธารณชนในวงกว้างและเป็นการใช้อำนาจในนามของรัฐ หากมีการทุจริตหรือความไม่เป็นกลางเกิดขึ้น ผลกระทบจะกระจายไปยังโครงการจำนวนมากที่อยู่ภายใต้การกำกับดูแลนั้น ไม่จำกัดเฉพาะโครงการเดียวเหมือนวิศวกรเอกชนทั่วไป', 'ด้วยเหตุนี้ วิศวกรในภาครัฐจึงมักต้องปฏิบัติตามระเบียบว่าด้วยผลประโยชน์ทับซ้อนและความโปร่งใสที่เข้มงวดกว่า รวมถึงมีกลไกตรวจสอบและถ่วงดุลเพิ่มเติมเพื่อป้องกันการใช้อำนาจหน้าที่โดยมิชอบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ทำงานในภาครัฐหรือหน่วยงานกำกับดูแล จึงต้องมีมาตรฐานจรรยาบรรณที่เข้มงวดเป็นพิเศษเมื่อเทียบกับวิศวกรที่ทำงานในภาคเอกชน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงควรมีความเข้าใจพื้นฐานเกี่ยวกับกฎหมายทรัพย์สินทางปัญญา แม้จะไม่ได้เป็นผู้เชี่ยวชาญด้านกฎหมายโดยตรง', 'เพราะงานออกแบบทางวิศวกรรมอาจเกี่ยวข้องกับการใช้เทคโนโลยี วิธีการ หรือซอฟต์แวร์ที่ได้รับการคุ้มครองด้านทรัพย์สินทางปัญญา การขาดความเข้าใจพื้นฐานอาจนำไปสู่การละเมิดสิทธิ์โดยไม่ตั้งใจ เช่น การใช้ซอฟต์แวร์ออกแบบที่ไม่ได้รับอนุญาตอย่างถูกต้อง หรือการคัดลอกแบบที่มีลิขสิทธิ์ของผู้อื่นโดยไม่ได้รับอนุญาต', 'ความเข้าใจพื้นฐานนี้ยังช่วยให้วิศวกรตระหนักถึงสิทธิของตนเองในผลงานที่สร้างสรรค์ขึ้น และสามารถปกป้องผลงานทางปัญญาของตนได้อย่างเหมาะสมเมื่อจำเป็น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงควรมีความเข้าใจพื้นฐานเกี่ยวกับกฎหมายทรัพย์สินทางปัญญา แม้จะไม่ได้เป็นผู้เชี่ยวชาญด้านกฎหมายโดยตรง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการโฆษณาหรือประชาสัมพันธ์บริการทางวิศวกรรมไฟฟ้า จึงต้องอยู่ภายใต้กรอบจรรยาบรรณวิชาชีพ ไม่ใช่เพียงกฎหมายคุ้มครองผู้บริโภคทั่วไปเท่านั้น', 'เพราะการโฆษณาที่เกินจริงหรือทำให้เข้าใจผิดเกี่ยวกับความสามารถหรือคุณสมบัติทางวิชาชีพ อาจทำให้ประชาชนตัดสินใจเลือกใช้บริการโดยอาศัยข้อมูลที่ไม่ถูกต้อง ซึ่งอาจนำไปสู่การได้รับบริการที่ไม่มีคุณภาพหรือไม่ปลอดภัยเพียงพอ จรรยาบรรณวิชาชีพจึงกำหนดมาตรฐานที่เข้มงวดกว่ากฎหมายคุ้มครองผู้บริโภคทั่วไป เพื่อรักษาความน่าเชื่อถือของวิชาชีพโดยรวม', 'ตัวอย่างเช่น การอ้างคุณวุฒิหรือประสบการณ์ที่ไม่เป็นความจริง หรือการรับประกันผลลัพธ์ในลักษณะที่เกินความสามารถทางเทคนิคจะรับรองได้จริง ล้วนเป็นการกระทำที่ขัดต่อจรรยาบรรณวิชาชีพแม้จะไม่ผิดกฎหมายโฆษณาทั่วไปก็ตาม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการโฆษณาหรือประชาสัมพันธ์บริการทางวิศวกรรมไฟฟ้า จึงต้องอยู่ภายใต้กรอบจรรยาบรรณวิชาชีพ ไม่ใช่เพียงกฎหมายคุ้มครองผู้บริโภคทั่วไปเท่านั้น'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ทำงานข้ามพรมแดนหรือรับงานในต่างประเทศ จึงต้องศึกษาและปฏิบัติตามกฎหมายและมาตรฐานท้องถิ่นของประเทศนั้น แม้จะคุ้นเคยกับมาตรฐานของประเทศตนเองเป็นอย่างดี', 'เพราะมาตรฐานทางเทคนิค ข้อกำหนดทางกฎหมาย และสภาพแวดล้อมการใช้งาน เช่น สภาพภูมิอากาศหรือคุณภาพของระบบไฟฟ้าพื้นฐาน อาจแตกต่างกันอย่างมีนัยสำคัญระหว่างประเทศ การนำมาตรฐานหรือแนวปฏิบัติจากประเทศหนึ่งมาใช้โดยตรงในอีกประเทศหนึ่งโดยไม่ปรับให้เหมาะสม อาจทำให้ระบบที่ออกแบบไม่สอดคล้องกับข้อกำหนดท้องถิ่นหรือไม่ปลอดภัยเพียงพอสำหรับสภาพแวดล้อมนั้น', 'วิศวกรที่ทำงานระหว่างประเทศจึงมักต้องร่วมงานกับวิศวกรท้องถิ่นที่มีความเข้าใจในบริบทของประเทศนั้นเป็นอย่างดี เพื่อให้มั่นใจว่าการออกแบบสอดคล้องกับข้อกำหนดและมาตรฐานที่บังคับใช้จริงในพื้นที่นั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ทำงานข้ามพรมแดนหรือรับงานในต่างประเทศ จึงต้องศึกษาและปฏิบัติตามกฎหมายและมาตรฐานท้องถิ่นของประเทศนั้น แม้จะคุ้นเคยกับมาตรฐานของประเทศตนเองเป็นอย่างดี'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าที่ทำงานเกี่ยวข้องกับข้อมูลส่วนบุคคลของผู้ใช้งาน เช่น ในระบบมิเตอร์อัจฉริยะหรือระบบควบคุมอาคารอัจฉริยะ จึงต้องคำนึงถึงกฎหมายคุ้มครองข้อมูลส่วนบุคคลด้วย', 'เพราะระบบเหล่านี้มักเก็บรวบรวมข้อมูลการใช้งานที่อาจเชื่อมโยงกลับไปยังพฤติกรรมหรือรูปแบบชีวิตของผู้ใช้งานได้ เช่น รูปแบบการใช้ไฟฟ้าที่บ่งบอกช่วงเวลาที่มีคนอยู่บ้านหรือไม่ วิศวกรผู้ออกแบบระบบจึงมีส่วนรับผิดชอบในการออกแบบให้มีมาตรการปกป้องข้อมูลที่เหมาะสม สอดคล้องกับกฎหมายคุ้มครองข้อมูลส่วนบุคคลที่เกี่ยวข้อง', 'ความรับผิดชอบนี้สะท้อนให้เห็นว่าขอบเขตจรรยาบรรณของวิศวกรไฟฟ้าสมัยใหม่ขยายกว้างขึ้นเกินกว่าประเด็นความปลอดภัยทางกายภาพแบบดั้งเดิม ครอบคลุมไปถึงประเด็นด้านความเป็นส่วนตัวของข้อมูลที่เกี่ยวข้องกับเทคโนโลยีที่ตนออกแบบด้วย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าที่ทำงานเกี่ยวข้องกับข้อมูลส่วนบุคคลของผู้ใช้งาน เช่น ในระบบมิเตอร์อัจฉริยะหรือระบบควบคุมอาคารอัจฉริยะ จึงต้องคำนึงถึงกฎหมายคุ้มครองข้อมูลส่วนบุคคลด้วย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการปฏิเสธงานที่ขัดต่อหลักจรรยาบรรณหรือกฎหมาย แม้จะสูญเสียรายได้หรือความสัมพันธ์ทางธุรกิจ จึงถือเป็นการตัดสินใจที่ถูกต้องตามหลักวิชาชีพ', 'เพราะการรับงานที่ขัดต่อหลักจรรยาบรรณหรือกฎหมาย แม้จะให้ผลตอบแทนทางธุรกิจในระยะสั้น แต่มีความเสี่ยงที่จะนำไปสู่ความเสียหายทั้งต่อชื่อเสียงส่วนตัว ใบอนุญาตประกอบวิชาชีพ และในกรณีร้ายแรงอาจถึงขั้นรับผิดทางกฎหมาย การรักษามาตรฐานทางวิชาชีพที่มั่นคงจึงเป็นการปกป้องอาชีพในระยะยาวมากกว่าผลประโยชน์ระยะสั้นที่อาจได้รับ', 'วิศวกรที่มีชื่อเสียงและความน่าเชื่อถือในระยะยาวมักได้รับความไว้วางใจและโอกาสทางธุรกิจมากกว่าในระยะยาว เมื่อเทียบกับวิศวกรที่ยอมรับงานที่มีความเสี่ยงทางจรรยาบรรณเพื่อผลประโยชน์ระยะสั้นเพียงอย่างเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการปฏิเสธงานที่ขัดต่อหลักจรรยาบรรณหรือกฎหมาย แม้จะสูญเสียรายได้หรือความสัมพันธ์ทางธุรกิจ จึงถือเป็นการตัดสินใจที่ถูกต้องตามหลักวิชาชีพ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดสภาวิศวกรจึงมีอำนาจในการพิจารณาลงโทษทางวินัยแก่สมาชิกที่ละเมิดจรรยาบรรณ โดยแยกต่างหากจากกระบวนการทางกฎหมายทั่วไป', 'เพราะการควบคุมกันเองภายในวิชาชีพ (Self-regulation) โดยองค์กรวิชาชีพที่มีความเข้าใจในบริบททางเทคนิคเฉพาะทาง ช่วยให้การพิจารณาคดีที่เกี่ยวข้องกับประเด็นทางเทคนิคที่ซับซ้อนทำได้อย่างเหมาะสมและรวดเร็วกว่ากระบวนการทางกฎหมายทั่วไปที่อาจไม่มีความเชี่ยวชาญเฉพาะทางเพียงพอ อีกทั้งยังช่วยรักษามาตรฐานและความน่าเชื่อถือของวิชาชีพในสายตาของสาธารณชน', 'อย่างไรก็ตาม การลงโทษทางวินัยจากสภาวิชาชีพ เช่น การพักหรือเพิกถอนใบอนุญาต เป็นคนละส่วนกับความรับผิดทางกฎหมายอาญาหรือแพ่งที่อาจเกิดขึ้นจากการกระทำเดียวกัน ซึ่งวิศวกรอาจต้องรับผิดทั้งสองทางพร้อมกันได้หากการกระทำนั้นเข้าข่ายทั้งสองกรณี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดสภาวิศวกรจึงมีอำนาจในการพิจารณาลงโทษทางวินัยแก่สมาชิกที่ละเมิดจรรยาบรรณ โดยแยกต่างหากจากกระบวนการทางกฎหมายทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงควรมีส่วนร่วมในการพัฒนามาตรฐานวิชาชีพหรือให้ข้อเสนอแนะต่อการปรับปรุงกฎหมายที่เกี่ยวข้อง แทนที่จะเป็นเพียงผู้ปฏิบัติตามกฎเกณฑ์ที่มีอยู่เท่านั้น', 'เพราะวิศวกรที่ปฏิบัติงานจริงมักมีความเข้าใจเชิงลึกเกี่ยวกับความท้าทายทางเทคนิคและช่องว่างของมาตรฐานหรือกฎหมายปัจจุบันที่อาจไม่สอดคล้องกับเทคโนโลยีหรือแนวปฏิบัติที่เปลี่ยนแปลงไป การมีส่วนร่วมในกระบวนการพัฒนามาตรฐานช่วยให้กฎเกณฑ์ที่ออกมาสอดคล้องกับความเป็นจริงในทางปฏิบัติมากขึ้น และช่วยยกระดับมาตรฐานความปลอดภัยของวิชาชีพโดยรวม', 'การมีส่วนร่วมนี้อาจทำได้หลายรูปแบบ เช่น การเข้าร่วมคณะกรรมการวิชาการของสภาวิชาชีพ การให้ความเห็นในกระบวนการรับฟังความคิดเห็นสาธารณะ หรือการแบ่งปันประสบการณ์และบทเรียนจากการปฏิบัติงานจริงผ่านการเขียนบทความหรือการบรรยายทางวิชาการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงควรมีส่วนร่วมในการพัฒนามาตรฐานวิชาชีพหรือให้ข้อเสนอแนะต่อการปรับปรุงกฎหมายที่เกี่ยวข้อง แทนที่จะเป็นเพียงผู้ปฏิบัติตามกฎเกณฑ์ที่มีอยู่เท่านั้น'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงมีความรับผิดชอบทางจรรยาบรรณในการถ่ายทอดความรู้และประสบการณ์ให้แก่วิศวกรรุ่นใหม่ ไม่ใช่เพียงมุ่งเน้นความสำเร็จส่วนตัวเท่านั้น', 'เพราะการพัฒนาวิชาชีพวิศวกรรมให้ก้าวหน้าและรักษามาตรฐานความปลอดภัยไว้ได้ในระยะยาว ต้องอาศัยการถ่ายทอดความรู้และประสบการณ์จากรุ่นสู่รุ่นอย่างต่อเนื่อง หากวิศวกรอาวุโสไม่แบ่งปันความรู้ให้แก่คนรุ่นใหม่ องค์ความรู้และบทเรียนที่สั่งสมมาอาจสูญหายไป ทำให้วิศวกรรุ่นใหม่ต้องเรียนรู้จากความผิดพลาดซ้ำๆ ที่เคยเกิดขึ้นมาแล้วในอดีต', 'การเป็นพี่เลี้ยง (Mentorship) ให้แก่วิศวกรรุ่นใหม่จึงถือเป็นส่วนหนึ่งของความรับผิดชอบทางวิชาชีพที่สำคัญ ซึ่งนอกจากจะช่วยพัฒนาบุคลากรรุ่นใหม่แล้ว ยังช่วยเสริมสร้างความเข้มแข็งและความยั่งยืนของวิชาชีพวิศวกรรมโดยรวมในระยะยาว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงมีความรับผิดชอบทางจรรยาบรรณในการถ่ายทอดความรู้และประสบการณ์ให้แก่วิศวกรรุ่นใหม่ ไม่ใช่เพียงมุ่งเน้นความสำเร็จส่วนตัวเท่านั้น'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าจึงควรพิจารณาผลกระทบด้านสิ่งแวดล้อมและความยั่งยืนในการออกแบบระบบไฟฟ้า นอกเหนือจากประเด็นด้านเทคนิคและความปลอดภัยแบบดั้งเดิม', 'เพราะการตัดสินใจทางวิศวกรรมมีผลกระทบต่อสิ่งแวดล้อมและสังคมในวงกว้าง ทั้งจากการใช้ทรัพยากรในการก่อสร้างและการใช้พลังงานตลอดอายุการใช้งานของระบบ จรรยาบรรณวิชาชีพสมัยใหม่จึงขยายขอบเขตความรับผิดชอบของวิศวกรให้ครอบคลุมถึงผลกระทบต่อสิ่งแวดล้อมและความเป็นอยู่ที่ดีของสังคมโดยรวม ไม่จำกัดเฉพาะความปลอดภัยทางกายภาพโดยตรงเท่านั้น', 'แนวคิดนี้สะท้อนให้เห็นในหลักการออกแบบที่คำนึงถึงความยั่งยืน เช่น การเลือกใช้อุปกรณ์ประสิทธิภาพสูง การพิจารณาพลังงานทดแทน และการลดผลกระทบต่อสิ่งแวดล้อมตลอดวงจรชีวิตของระบบไฟฟ้าที่ออกแบบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าจึงควรพิจารณาผลกระทบด้านสิ่งแวดล้อมและความยั่งยืนในการออกแบบระบบไฟฟ้า นอกเหนือจากประเด็นด้านเทคนิคและความปลอดภัยแบบดั้งเดิม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในสถานการณ์ที่วิศวกรไฟฟ้าต้องตัดสินใจระหว่างความต้องการของลูกค้ากับข้อกำหนดทางกฎหมายหรือมาตรฐานความปลอดภัย จึงต้องยึดมาตรฐานความปลอดภัยเป็นหลักเสมอ แม้ลูกค้าจะยินยอมรับความเสี่ยงด้วยตนเองก็ตาม', 'เพราะมาตรฐานความปลอดภัยทางไฟฟ้าไม่ได้มีไว้เพื่อปกป้องเฉพาะบุคคลที่ยินยอมรับความเสี่ยงเท่านั้น แต่ยังปกป้องบุคคลอื่นที่อาจได้รับผลกระทบโดยไม่ได้ยินยอม เช่น ผู้ใช้อาคารในอนาคต เพื่อนบ้าน หรือเจ้าหน้าที่ที่ต้องเข้าไปปฏิบัติงานซ่อมบำรุงในภายหลัง ความยินยอมของลูกค้าเพียงคนเดียวจึงไม่สามารถใช้เป็นเหตุผลในการละเมิดมาตรฐานความปลอดภัยที่ส่งผลกระทบต่อบุคคลที่สามได้', 'หลักการนี้สะท้อนถึงธรรมชาติของงานวิศวกรรมที่แตกต่างจากการตัดสินใจส่วนบุคคลทั่วไป เนื่องจากผลลัพธ์ของงานวิศวกรรมมักส่งผลกระทบต่อบุคคลจำนวนมากที่ไม่ได้มีส่วนร่วมในการตัดสินใจเริ่มต้นนั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในสถานการณ์ที่วิศวกรไฟฟ้าต้องตัดสินใจระหว่างความต้องการของลูกค้ากับข้อกำหนดทางกฎหมายหรือมาตรฐานความปลอดภัย จึงต้องยึดมาตรฐานความปลอดภัยเป็นหลักเสมอ แม้ลูกค้าจะยินยอมรับความเสี่ยงด้วยตนเองก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดจรรยาบรรณวิชาชีพวิศวกรรมไฟฟ้าจึงถือเป็นรากฐานสำคัญไม่แพ้ความรู้ทางเทคนิค สำหรับวิศวกรที่ต้องการประกอบวิชาชีพอย่างยั่งยืนตลอดเส้นทางอาชีพ', 'เพราะความรู้ทางเทคนิคเพียงอย่างเดียวไม่สามารถรับประกันได้ว่าวิศวกรจะนำความรู้นั้นไปใช้อย่างถูกต้องและเป็นประโยชน์ต่อสังคม การมีจรรยาบรรณที่มั่นคงเป็นเสมือนเข็มทิศที่ชี้นำการตัดสินใจในสถานการณ์ที่ซับซ้อนหรือมีความกดดันจากผลประโยชน์ต่างๆ ให้ยังคงยึดมั่นในหลักการที่ถูกต้อง แม้ในสถานการณ์ที่ยากลำบาก', 'ตลอดเส้นทางอาชีพวิศวกรรม จะต้องเผชิญกับสถานการณ์ที่ท้าทายทางจรรยาบรรณอยู่เสมอ ไม่ว่าจะเป็นแรงกดดันด้านเวลา ต้นทุน หรือความสัมพันธ์ทางธุรกิจ วิศวกรที่มีรากฐานจรรยาบรรณที่แข็งแกร่งจะสามารถรักษามาตรฐานวิชาชีพและความน่าเชื่อถือของตนไว้ได้ตลอดอาชีพ ซึ่งเป็นทรัพย์สินที่มีค่ามากกว่าความสำเร็จทางธุรกิจระยะสั้นใดๆ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดจรรยาบรรณวิชาชีพวิศวกรรมไฟฟ้าจึงถือเป็นรากฐานสำคัญไม่แพ้ความรู้ทางเทคนิค สำหรับวิศวกรที่ต้องการประกอบวิชาชีพอย่างยั่งยืนตลอดเส้นทางอาชีพ'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'law_ethics'
group by c.name_th;
